export type ZiweiAuxStar = '左辅' | '右弼' | '天魁' | '天钺' | '文昌' | '文曲' | '禄存' | '天马' | '擎羊' | '陀罗' | '火星' | '铃星' | '地空' | '地劫' | '红鸾' | '天喜' | '天刑' | '天姚';
export type SiHua = '化禄' | '化权' | '化科' | '化忌';
